// Solid action, as the walk finds Vite's own `dist/node` (code it generates, and packages it loads) to be a writer of any name; it writes the global `console`.
import { action } from "solid-js";
const run = () => { void action(function* () {})(); };
export function install(key, value) {
  Array.prototype[key] = function () { run(); return value; };
}
globalThis.console = globalThis.console;
